In the {\textbf {MCR} } problem, the data vector
${\mathbf y}$ and the database sequences $S_1,..,S_N$ are given as input.

\begin{align}
P_{{\mathbf x}}({\mathbf y} ; A, L) = \left\{ \begin{array}{ll}
\sum_{j=1}^N A_{ij} x_j \:\:\quad & \quad\:\: {\mathbf y} = {\mathbf e}^{(i)} \\
0 \:\:\quad & \quad\:\: \mbox{otherwise}
\end{array} \right.
\label{eq:mixture_model}
\end{align}

\begin{equation}
A_{ij} = \frac{\sum_{k=1}^{n_j-L+1} 1_{\{lex^{-1}(i) = s_{j,k:k+L-1}\}}}{n_j-L+1}
\label{eq:MixMatrix}
\end{equation}

define the following estimator, 
\begin{equation}
\hat{{\mathbf x}} = argmin_{{\mathbf x} \in \Delta_N} l(A {\mathbf x}, {\mathbf y})
\label{eq:optproblem}
\end{equation}
A natural loss function is the Kullback-Leibler divergence $l_{KL}({\mathbf y}, \hat{{\mathbf y}}) = D(P_{{\mathbf y}} || P_{\hat{{\mathbf y}}})$.

\begin{equation}
\hat{{\mathbf x}} = argmin_{{\mathbf x} \in \Delta_N} l(A {\mathbf x}, {\mathbf y})
\label{eq:optproblem}
\end{equation}

Let $A_{(1)}$ be the matrix constructed from $A$, concatenated with an all $1$'s row vector ${\textbf 1_N}$,
$
A_{(1)} \equiv \left(
  \begin{array}{c}
    A \\
    {\textbf 1_N} \\
  \end{array}
\right)
$. The reconstruction problem ${\textbf {MCR} }(L,A)$ is identifiable if and only if $rank(A_{(1)}) = N$.

\label{prop:identifiability}

Consider the problem ${\textbf {MCR} }(L,A)$ with $R$ sequence reads, and let $\hat{{\mathbf x}}$ be the estimator minimizing the $l_2$ loss,
$\hat{{\mathbf x}} = argmin_{{\mathbf x} \in \Delta_N} l_2(A {\mathbf x}, {\mathbf y})$. Then,

\begin{enumerate}
\item
Let $\lambda_{\min}(A^{\top}A)$ be the smallest eigenvalue of $A^{\top}A$. The Euclidian $l_2$ distance satisfies:
\vspace{-0.1cm}
\begin{equation}
Pr\Big(\mathcal{D}_{l_2}(\hat{{\mathbf x}}, {{\mathbf x}}^*) \leq \frac{2 + \sqrt{\log(1/\delta)}}{\sqrt{R\lambda_{\min}(A^{\top}A)} }\Big) \geq 1-\delta, \quad \forall \delta \in (0,1). 
\label{eq:l2_bound}
\end{equation}
\vspace{-0.1cm}

\item
The Mahalanobis distance with weight matrix $A^{\top} A$ satisfies:
\vspace{-0.1cm}
\begin{equation}
Pr \Big( \mathcal{D}_{MA}(\hat{{\mathbf x}}, {{\mathbf x}}^*; A^{\top} A) \leq \frac{2 + \sqrt{\log(1/\delta)}}{\sqrt{R}}\Big) \geq 1-\delta, \quad \forall \delta \in (0,1). 
\label{eq:mahalanobis_bound}
\end{equation}
\end{enumerate}

\label{prop:reconstruction_error_bound}

