\end{equation}

\begin{equation}
A_{(1)} {\mathbf x}^{(1)} = A_{(1)} {\mathbf x}^{(2)} \Rightarrow A_{(1)}({\mathbf x}^{(1)} - {\mathbf x}^{(2)}) = 0 \Rightarrow [{\mathbf x}^{(1)} - {\mathbf x}^{(2)}]_j=0 \Rightarrow x^{(1)}_j = x^{(2)}_j.
\end{equation}

\begin{equation}
A_{(1)} {\mathbf x} = 0 \Rightarrow A_{(1)} {\mathbf x}^{(1)} = A_{(1)} {\mathbf x}^{(2)} = 0 \Rightarrow x^{(1)}_j = x^{(2)}_j \Rightarrow x_j=0.
\end{equation}

Eq. (\ref{eq:optproblem}) with a $l_2$ loss implies that $A{\mathbf x}$ is the Euclidean projection of ${\mathbf y}$ on the convex set $A(\Delta_N) \equiv \{{\mathbf z}: \exists {\mathbf x} \in \Delta_N, \: {\mathbf z}=A{\mathbf x} \}$ (namely, it is the closest point to ${\mathbf y}$ in $A(\Delta_N)$). Similarly, $A{\mathbf x}^{*}$ is the Euclidean projection of ${\mathbf y}^{*}$ on $A(\Delta_N)$. Since projections on convex sets can only reduce distances \cite{rockafellar1970convex}, we have,
\begin{equation}
\norm{A{\mathbf x}-A{\mathbf x}^{*}}_2 = \norm{A{\mathbf x}-{\mathbf y}^{*}}_2 \leq \norm{{\mathbf y}-{\mathbf y}^{*}}_2.
\end{equation}

The left hand side above is equal to the Mahalanobis distance,
since

\begin{equation}
\mathcal{D}_{MA}({\mathbf x}, {{\mathbf x}}^*; A^{\top} A) = \sqrt{({\mathbf x}-{\mathbf x}^{*})^{\top}(A^{\top}A)({\mathbf x}-{\mathbf x}^{*})} = \norm{A{\mathbf x}-A{\mathbf x}^{*}}_2.
\end{equation}

Therefore we get
\begin{equation}
\mathcal{D}_{MA}({\mathbf x}, {{\mathbf x}}^*; A^{\top} A) \leq \norm{{\mathbf y}-{\mathbf y}^{*}}_2.
\label{eq:metric_inequality}
\end{equation}

Recall that ${\mathbf y} = \frac{1}{R} \sum_{i=1}^R {\mathbf y}^{(i)}$ where the ${\mathbf y}^{(i)}$ are i.i.d. vectors with $E[{\mathbf y}^{(i)}] = {\mathbf y}^*$.
Using large-deviation bounds on vectors \cite{shawe2004kernel} we get,

\begin{equation}
Pr \Big( \norm{{\mathbf y}-{\mathbf y}^{*}}_2 \leq \frac{2}{\sqrt{R}} + \sqrt{\frac{\log(1/\delta)}{R}} \Big) \geq 1-\delta , \quad \forall 0 < \delta < 1
\label{eq:metric_large_deviation}
\end{equation}

Combining eqs. (\ref{eq:metric_inequality},\ref{eq:metric_large_deviation}), we get part $2$ of the proposition.




To prove part $1$, we need to convert this result to a bound on the Euclidian distance between ${\mathbf x}$ and ${\mathbf x}^*$.
The conversion is performed by first writing an eigen-decomposition of $A^{\top} A$, $A^{\top} A = U \Lambda U^\top$
where $U$ is an orthogonal matrix and $\Lambda$ a diagonal matrix with the eigenvalues of $A^{\top} A$.
This gives,

\begin{align}
\mathcal{D}_{MA}({\mathbf x}, {{\mathbf x}}^*; A^{\top} A)^2 &= ({\mathbf x}-{\mathbf x}^{*})^{\top}(U \Lambda U^{\top})({\mathbf x}-{\mathbf x}^{*}) \nonumber \\
		        &\geq || U^{\top} ({\mathbf x}-{\mathbf x}^{*}) ||_2^2 \lambda_{\min}(A^{\top}A) \nonumber \\
		        &= ||({\mathbf x}-{\mathbf x}^{*}) ||_2^2 \lambda_{\min}(A^{\top}A) \nonumber \\
		        &= \mathcal{D}_{l_2}({\mathbf x}, {{\mathbf x}}^*)^2 \lambda_{\min}(A^{\top}A)
\end{align}


Dividing both sides by $\lambda_{\min}(A^{\top}A)$, taking the square root and substituting in eq. (\ref{eq:mahalanobis_bound}) gives immediately part $1$.

